(function () {
  'use strict';
  try {
    if (window.__iceBlackGround) return;
    window.__iceBlackGround = 1;
    var queued = false;
    function paint(el) {
      if (!el || !el.style) return;
      var s = el.style;
      if (s.getPropertyValue('background-color') !== 'rgb(0, 0, 0)' || s.getPropertyPriority('background-color') !== 'important')
        s.setProperty('background-color', '#000', 'important');
      if (s.getPropertyValue('background-image') !== 'none' || s.getPropertyPriority('background-image') !== 'important')
        s.setProperty('background-image', 'none', 'important');
    }
    function applyAll() {
      queued = false;
      try {
        var d = document;
        paint(d.documentElement); paint(d.body);
        paint(d.getElementById('bod')); paint(d.getElementById('can'));
      } catch (e) {}
    }
    function schedule() {
      if (queued) return;
      queued = true;
      (window.requestAnimationFrame || setTimeout)(applyAll, 50);
    }
    function start() {
      applyAll();
      try {
        var mo = new MutationObserver(schedule);
        var d = document;
        [d.documentElement, d.body, d.getElementById('bod'), d.getElementById('can')].forEach(function (el) {
          if (el) mo.observe(el, { attributes: true, attributeFilter: ['style', 'class'] });
        });
      } catch (e) {}
      var n = 0, t = setInterval(function () { applyAll(); if (++n >= 20) clearInterval(t); }, 1000);
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
    else start();
  } catch (e) {}
})();

/* ice perf f3: uses ONLY the game's own localStorage key "particles" (0=off,1=low,2=high; game default 2).
   Read by the client at every game start (reset()). No built-ins patched, no intervals, client.js untouched. */
(function () {
  try {
    if (window.__icePerf) return; window.__icePerf = 1;
    var ls = window.localStorage;
    if (ls && ls.getItem('particles') !== '0') ls.setItem('particles', '0');
  } catch (e) {}
})();

/* ice perf f4: hide the 970x250 menu ad slot (element kept in DOM; client only checks #trevda/#preroll exist). */
#bebebaba,#devast-io_970x250{display:none !important}
/* stop decorative CSS animations/transitions on HTML UI only; canvas is drawn by JS and unaffected */
body *:not(canvas){animation-duration:0s !important;animation-iteration-count:1 !important;transition-duration:0s !important}

/* ice clan colour (f5): edit --clan-color to change the colour of the HTML clan menu (main menu only). */
:root{--clan-color:#3fe0e8}
#clanButton{border-color:var(--clan-color) !important;box-shadow:0 0 0 .15em var(--clan-color) !important}
#clanButtonBadge,#clanPopup .dv-tab.dv-on{background-color:var(--clan-color) !important;color:#001418 !important}
#clanPopup .dv-window{border-color:var(--clan-color) !important;box-shadow:0 0 .6em var(--clan-color) !important}
#clanPopup .dv-title,#clanPopup .dv-window-head,#clanPopup [class*="clan-name"],#clanPopup [class*="clan-tag"]{color:var(--clan-color) !important}

/* ice f6: in-game clan colour menu. Plain DOM only. Controls the CSS variable --clan-color
   (used by f5 for the HTML clan menu). Canvas sprites are NOT affected (static overrides). Hotkey: F8. */
(function () {
  'use strict';
  try {
    if (window.__iceClanMenu) return; window.__iceClanMenu = 1;
    var KEY = 'iceClanColor', DEF = '#3fe0e8';
    var PRE = [['Turquoise', '#3fe0e8'], ['Pink', '#ff5fb4'], ['Gold', '#ffc83a'], ['Red', '#ff3b3b']];
    function norm(v) { v = String(v || '').trim(); if (v[0] !== '#') v = '#' + v;
      if (/^#[0-9a-f]{3}$/i.test(v)) v = '#' + v[1] + v[1] + v[2] + v[2] + v[3] + v[3];
      return /^#[0-9a-f]{6}$/i.test(v) ? v.toLowerCase() : null; }
    var cur = DEF; try { cur = norm(localStorage.getItem(KEY)) || DEF; } catch (e) {}
    function apply(c, save) { c = norm(c); if (!c) return; cur = c;
      try { document.documentElement.style.setProperty('--clan-color', c); } catch (e) {}
      if (save) try { localStorage.setItem(KEY, c); } catch (e) {}
      if (ui) { ui.pick.value = c; if (document.activeElement !== ui.hex) ui.hex.value = c;
        ui.btn.style.color = c; ui.prev.style.background = c; } }
    var ui = null; apply(cur, false);
    function build() {
      if (ui || !document.body) return;
      var st = document.createElement('style');
      st.textContent = '#iceClanBtn{position:fixed;left:8px;bottom:8px;z-index:2147483000;width:30px;height:30px;border-radius:50%;border:1px solid rgba(120,230,255,.6);background:rgba(4,20,28,.75);font:18px/28px sans-serif;text-align:center;cursor:pointer;user-select:none;padding:0;box-shadow:0 0 6px rgba(90,220,255,.4)}' +
        '#iceClanPanel{position:fixed;left:8px;bottom:46px;z-index:2147483000;width:200px;padding:10px;border-radius:8px;background:rgba(6,24,34,.92);border:1px solid rgba(120,230,255,.55);box-shadow:0 0 12px rgba(80,220,255,.35);color:#cff6ff;font:12px sans-serif;display:none}' +
        '#iceClanPanel h4{margin:0 0 8px;font-size:13px;color:#8eeeff;letter-spacing:.05em}' +
        '#iceClanPanel .sw{display:inline-block;width:38px;height:22px;margin:0 4px 6px 0;border-radius:4px;border:1px solid rgba(255,255,255,.35);cursor:pointer}' +
        '#iceClanPanel input[type=color]{width:40px;height:26px;border:0;padding:0;background:none;vertical-align:middle;cursor:pointer}' +
        '#iceClanPanel input[type=text]{width:84px;margin-left:6px;padding:3px 5px;background:#021017;color:#cff6ff;border:1px solid rgba(120,230,255,.5);border-radius:4px;font:12px monospace;vertical-align:middle}' +
        '#iceClanPanel .pv{display:inline-block;width:22px;height:22px;border-radius:50%;margin-left:6px;vertical-align:middle;border:1px solid #fff4}' +
        '#iceClanPanel .nt{margin-top:8px;font-size:10px;opacity:.7;line-height:1.3}';
      (document.head || document.documentElement).appendChild(st);
      var btn = document.createElement('button'); btn.id = 'iceClanBtn'; btn.type = 'button'; btn.title = 'Clan colour (F8)'; btn.textContent = '\u2744';
      var p = document.createElement('div'); p.id = 'iceClanPanel';
      p.innerHTML = '<h4>\u2744 CLAN COLOUR</h4><div class="sws"></div><input type="color"><input type="text" maxlength="7" spellcheck="false"><span class="pv"></span>' +
        '<div class="nt">Changes the clan menu (HTML). Map arrow / team sprites use the preset set in the pack.</div>';
      var sws = p.querySelector('.sws');
      PRE.forEach(function (x) { var s = document.createElement('span'); s.className = 'sw'; s.title = x[0]; s.style.background = x[1];
        s.addEventListener('click', function () { apply(x[1], true); }); sws.appendChild(s); });
      ui = { btn: btn, panel: p, pick: p.querySelector('input[type=color]'), hex: p.querySelector('input[type=text]'), prev: p.querySelector('.pv') };
      ui.pick.addEventListener('input', function () { apply(ui.pick.value, true); });
      ui.hex.addEventListener('input', function () { var c = norm(ui.hex.value); if (c) apply(c, true); });
      ['keydown', 'keyup', 'keypress'].forEach(function (t) { ui.hex.addEventListener(t, function (e) {
        e.stopPropagation(); if (t === 'keydown' && (e.key === 'Enter' || e.key === 'Escape')) ui.hex.blur(); }); });
      ui.hex.addEventListener('blur', function () { ui.hex.value = cur; });
      btn.addEventListener('mousedown', function (e) { e.stopPropagation(); });
      p.addEventListener('mousedown', function (e) { e.stopPropagation(); });
      btn.addEventListener('click', function (e) { e.stopPropagation(); toggle(); });
      document.body.appendChild(btn); document.body.appendChild(p); apply(cur, false);
    }
    function toggle(force) { if (!ui) return; var open = force !== undefined ? force : ui.panel.style.display !== 'block';
      ui.panel.style.display = open ? 'block' : 'none';
      if (!open) { try { var a = document.activeElement; if (a && ui.panel.contains(a) || a === ui.btn) a.blur(); } catch (e) {} }
      else { try { ui.btn.blur(); } catch (e) {} } }
    window.addEventListener('keydown', function (e) { try { if (e.key === 'F8' || e.keyCode === 119) { e.preventDefault(); toggle(); } } catch (x) {} });
    if (document.body) build(); else document.addEventListener('DOMContentLoaded', build);
  } catch (e) {}
})();
